<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';require_once __DIR__ . '/../includes/auth.php';
$admin=current_user();if(!$admin||$admin['role']!=='Administrator'){http_response_code(403);exit('Access denied.');}
if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired. Refresh the page and try again.');}
$op=(string)($_POST['operation']??'');$guardian=filter_var($_POST['guardian_id']??null,FILTER_VALIDATE_INT);$pdo=db();
try{
 if($op==='create'){$password=(string)($_POST['password']??'');$confirm=(string)($_POST['password_confirm']??'');if(!$guardian||strlen($password)<12||!hash_equals($password,$confirm))throw new DomainException('Choose a consented guardian contact and a matching temporary password of at least 12 characters.');$pdo->beginTransaction();$q=$pdo->prepare("SELECT sg.id,sg.full_name,sg.email,sg.consent_status,l.user_id FROM student_guardians sg LEFT JOIN guardian_user_links l ON l.guardian_id=sg.id WHERE sg.id=:id FOR UPDATE");$q->execute(['id'=>$guardian]);$contact=$q->fetch();if(!$contact||$contact['consent_status']!=='Granted'||!$contact['email']||$contact['user_id'])throw new DomainException('This guardian contact is not eligible for a portal account.');$exists=$pdo->prepare('SELECT role FROM users WHERE email=:email');$exists->execute(['email'=>$contact['email']]);if($exists->fetch())throw new DomainException('That email already has an account. Use Link another child if it is an active guardian account.');$create=$pdo->prepare("INSERT INTO users (full_name,email,password_hash,role,active,must_change_password) VALUES (:name,:email,:hash,'Guardian',1,1)");$create->execute(['name'=>$contact['full_name'],'email'=>$contact['email'],'hash'=>password_hash($password,PASSWORD_DEFAULT)]);$userId=(int)$pdo->lastInsertId();$link=$pdo->prepare('INSERT INTO guardian_user_links (guardian_id,user_id,linked_by) VALUES (:guardian,:user,:admin)');$link->execute(['guardian'=>$guardian,'user'=>$userId,'admin'=>$admin['id']]);audit_log('guardian.portal_account_created','users',$userId,['guardian_contact_id'=>$guardian]);$pdo->commit();$_SESSION['notice']='Guardian login created. Share the temporary password privately; it must be changed at first sign-in.';}
 elseif($op==='link'){$userId=filter_var($_POST['user_id']??null,FILTER_VALIDATE_INT);if(!$guardian||!$userId)throw new DomainException('Choose an account and a guardian contact.');$pdo->beginTransaction();$g=$pdo->prepare("SELECT id,email,consent_status FROM student_guardians WHERE id=:id FOR UPDATE");$g->execute(['id'=>$guardian]);$contact=$g->fetch();$u=$pdo->prepare("SELECT id,email,active FROM users WHERE id=:id AND role='Guardian' FOR UPDATE");$u->execute(['id'=>$userId]);$account=$u->fetch();if(!$contact||$contact['consent_status']!=='Granted'||!$contact['email']||!$account||!$account['active']||strcasecmp($contact['email'],$account['email'])!==0)throw new DomainException('The account must be active, have the same verified email, and the guardian contact must have granted consent.');$link=$pdo->prepare('INSERT INTO guardian_user_links (guardian_id,user_id,linked_by) VALUES (:guardian,:user,:admin)');$link->execute(['guardian'=>$guardian,'user'=>$userId,'admin'=>$admin['id']]);audit_log('guardian.child_linked','guardian_user_links',$guardian,['user_id'=>$userId]);$pdo->commit();$_SESSION['notice']='The learner was linked to the guardian account.';}
 elseif($op==='status'){$userId=filter_var($_POST['user_id']??null,FILTER_VALIDATE_INT);$active=(int)($_POST['active']??0)===1?1:0;if(!$userId)throw new DomainException('Choose a guardian account.');$q=$pdo->prepare("UPDATE users SET active=:active WHERE id=:id AND role='Guardian'");$q->execute(['active'=>$active,'id'=>$userId]);if(!$q->rowCount())throw new DomainException('Guardian account not found or already has that status.');audit_log('guardian.portal_account_status','users',$userId,['active'=>(bool)$active]);$_SESSION['notice']='Guardian account status updated.';}
 else throw new DomainException('Unknown guardian account action.');
}catch(DomainException $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']=$e->getMessage();}catch(PDOException $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Guardian account save failed: '.$e->getMessage());$_SESSION['error']=$e->getCode()==='23000'?'This contact is already linked or the email is already in use.':'Could not save the guardian account.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Guardian account save failed: '.$e->getMessage());$_SESSION['error']='Could not save the guardian account.';}
header('Location: ../?page=settings&tab=guardians');exit;
